{"task": "Find log messages containing any character repeated three or more times consecutively", "sql": "SELECT * FROM logs WHERE regexp_like(message, '(.)\\1{2,}');"}
{"task": "Count how many log messages per service contain repeated character sequences", "sql": "SELECT service, COUNT(*) AS repeated_char_count FROM logs WHERE regexp_like(message, '(.)\\1{2,}') GROUP BY service ORDER BY repeated_char_count DESC;"}
{"task": "List error-level logs with excessive repeated letters, often indicating corrupted or spammy output", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([a-zA-Z])\\1{3,}');"}
{"task": "Flag log messages with repeated punctuation characters like multiple exclamation marks or dashes", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([!?\\-])\\1{2,}');"}
{"task": "Categorize each log message as having repeated digits, repeated letters, both, or neither using a CASE expression", "sql": "SELECT ts, message, CASE WHEN regexp_like(message, '([0-9])\\1{2,}') AND regexp_like(message, '([a-zA-Z])\\1{2,}') THEN 'both' WHEN regexp_like(message, '([0-9])\\1{2,}') THEN 'digits' WHEN regexp_like(message, '([a-zA-Z])\\1{2,}') THEN 'letters' ELSE 'none' END AS repeat_category FROM logs;"}
{"task": "Find the most recent 50 log entries that contain repeated whitespace characters, which may indicate formatting bugs", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\s{3,}') ORDER BY ts DESC LIMIT 50;"}
{"task": "Identify distinct services that have ever logged a message with four or more identical consecutive characters", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '(.)\\1{3,}');"}
{"task": "Compute the hourly trend of log messages containing repeated character patterns to spot spikes over time", "sql": "SELECT date_trunc('hour', ts) AS hour_bucket, COUNT(*) AS repeated_char_logs FROM logs WHERE regexp_like(message, '(.)\\1{2,}') GROUP BY hour_bucket ORDER BY hour_bucket;"}
{"task": "Search WARN and ERROR logs for repeated uppercase letters, which can signal shouting or alert-style messages", "sql": "SELECT ts, level, message FROM logs WHERE level IN ('WARN', 'ERROR') AND regexp_like(message, '([A-Z])\\1{2,}');"}
{"task": "Find log messages where a repeated character pattern appears alongside the word 'error', combining regex and text search", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '(.)\\1{2,}') AND message ILIKE '%error%';"}

